final boolean isLinkedWithAnyActiveLoan = this.accountAssociationsReadPlatformService.isLinkedWithAnyActiveAccount(savingsId);

if (isLinkedWithAnyActiveLoan) {
    final String defaultUserMessage = "Closing savings account with id:" + savingsId
            + " is not allowed, since it is linked with one of the active accounts";
    throw new SavingsAccountClosingNotAllowedException("linked", defaultUserMessage, savingsId);
}

// |WakeLockType::kPreventAppSuspension| keeps system active, but allows
// screen to be turned off.
// |WakeLockType::kPreventDisplaySleep| keeps system and screen active, has a
// higher precedence level than |WakeLockType::kPreventAppSuspension|.
//
// Only the highest-precedence blocker type takes effect.
device::mojom::WakeLockType new_lock_type =
    device::mojom::WakeLockType::kPreventAppSuspension;
for (const auto& element : wake_lock_types_) {
  if (element.second == device::mojom::WakeLockType::kPreventDisplaySleep) {
    new_lock_type = device::mojom::WakeLockType::kPreventDisplaySleep;
    break;
  }

BrowserWindow.getFocusedWindow = () => {
  for (const window of BrowserWindow.getAllWindows()) {
    if (!window.isDestroyed() && window.webContents && !window.webContents.isDestroyed()) {
      if (window.isFocused() || window.webContents.isDevToolsFocused()) return window;
    }
  }
  return null;

const resizableValues = new Map();
if (process.platform === 'darwin') {
  // Fix for bug in ScreenCaptureKit that modifies a window's styleMask the first time
  // it captures a non-resizable window. We record each non-resizable window's styleMask,
  // and we restore modified styleMasks later, after the screen capture.
  for (const win of BrowserWindow.getAllWindows()) {
    resizableValues.set([win.id], win.resizable);
  }

if (process.platform === 'darwin') {
  for (const win of BrowserWindow.getAllWindows()) {
    if (resizableValues.has(win.id)) {
